function companyData(value){if(!value||typeof value!=='object')return null;const result={...blankCompany};for(const key of Object.keys(result))if(typeof value[key]==='string')result[key]=value[key].trim().slice(0,180);const digits=result.siren.replace(/\D/g,'');if(!result.name||digits.length!==9)return null;result.siren=digits.replace(/(\d{3})(?=\d)/g,'$1 ');return result;}
