try{const sessionProfile=JSON.parse(sessionStorage.getItem('rg-demo-profile'));if(sessionProfile&&typeof sessionProfile==='object')for(const key of ['firstname','lastname'])if(typeof sessionProfile[key]==='string')profile[key]=sessionProfile[key].slice(0,120);}catch{}
let legacyCompany=null;try{legacyCompany=companyData(JSON.parse(localStorage.getItem('rg-demo-company')));}catch{}
if(!companies.length)companies=[{id:companyId(initialCompany),data:{...initialCompany},example:true,settings:{reminders:true,digest:false}}];
if(legacyCompany){const id=companyId(legacyCompany),entry=companies.find(c=>c.id===id);if(entry)entry.data=legacyCompany;else companies.push({id,data:legacyCompany,example:id===companyId(initialCompany),settings:{reminders:true,digest:false}});if(!selectedCompanyId)selectedCompanyId=id;}
const volumeSeeded=seedVolumeFixtures(companies);
initializeOrganizations(companies,profile);
