function informationPanel(){return `<section class="panel information-panel company-information-card"><div class="panel-heading"><div class="panel-title">${icon('building')}<h3>Informations générales</h3></div><button class="text-link" data-action="edit">${icon('edit')}Modifier</button></div>
  <dl class="info-list"><div class="info-row"><dt>Dénomination sociale</dt><dd>${escapeHTML(company.name)}</dd></div><div class="info-row"><dt>Forme juridique</dt><dd>${escapeHTML(company.form)}</dd></div><div class="info-row"><dt>Numéro SIREN</dt><dd class="number"><button class="copy-button" data-copy="${escapeHTML(company.siren)}" aria-label="Copier le SIREN">${escapeHTML(company.siren)} ${icon('file')}</button></dd></div><div class="info-row"><dt>SIRET du siège</dt><dd class="number"><button class="copy-button" data-copy="${escapeHTML(company.siret)}" aria-label="Copier le SIRET">${escapeHTML(company.siret)} ${icon('file')}</button></dd></div><div class="info-row"><dt>Date de création</dt><dd>${escapeHTML(company.created)}</dd></div><div class="info-row"><dt>Clôture de l’exercice</dt><dd>${escapeHTML(company.closing)}</dd></div><div class="info-row"><dt>Activité principale</dt><dd>${escapeHTML(company.activity)}</dd></div><div class="info-row address-row"><dt>Siège social</dt><dd><span>${escapeHTML(company.street)}</span><span>${escapeHTML(company.city)}</span><span>France</span></dd></div></dl><div class="panel-foot">${icon('shield')}Les informations de cette fiche restent associées à cette société.</div></section>`;}
