function emptyOwnership(){return {total:0,nominalCents:100,type:'Actions ordinaires',name:'',associates:[]};}
function initialOwnership(){return {total:1000,nominalCents:100,type:'Actions ordinaires',name:'',associates:[{id:'1',account:1,name:'Amélien Delahaie',kind:'Personne physique',shares:249,email:'',address:''},{id:'2',account:2,name:'Steve Rodgers',kind:'Personne physique',shares:751,email:'',address:''}]};}
function normalizeOwnership(value,example=false){if(!value||typeof value!=='object')return example?initialOwnership():emptyOwnership();const result=emptyOwnership();result.total=Number.isSafeInteger(value.total)&&value.total>=0&&value.total<=100000000?value.total:0;result.nominalCents=Number.isSafeInteger(value.nominalCents)&&value.nominalCents>0&&value.nominalCents<=1000000000?value.nominalCents:100;result.type=['Actions ordinaires','Actions de préférence','Parts sociales'].includes(value.type)?value.type:'Actions ordinaires';result.name=typeof value.name==='string'?value.name.slice(0,100):'';if(Array.isArray(value.associates))for(const row of value.associates.slice(0,1000)){if(!row||!/^\d+$/.test(String(row.id))||!Number.isSafeInteger(row.account)||row.account<1||!Number.isSafeInteger(row.shares)||row.shares<0||typeof row.name!=='string'||!row.name.trim())continue;if(result.associates.some(item=>item.id===String(row.id)||item.account===row.account))continue;result.associates.push({id:String(row.id),account:row.account,name:row.name.trim().slice(0,120),kind:row.kind==='Personne morale'?'Personne morale':'Personne physique',shares:row.shares,email:typeof row.email==='string'?row.email.slice(0,150):'',address:typeof row.address==='string'?row.address.slice(0,250):'',...normalizeAssociateExtras(row,example)});}if(allocatedShares(result)>result.total||!Number.isSafeInteger(result.total*result.nominalCents))return example?initialOwnership():emptyOwnership();return normalizeCapitalExtensions(value,result);}
function getOwnership(){if(!currentCompany.ownership)currentCompany.ownership=normalizeOwnership(null,currentCompany.example);for(const item of currentCompany.ownership.associates)if(item.ledgerVersion!==1)Object.assign(item,normalizeAssociateExtras(item,currentCompany.example));syncRegisterAccounts(currentCompany.ownership);return currentCompany.ownership;}
function allocatedShares(data=getOwnership()){return data.associates.reduce((sum,item)=>sum+item.shares,0);}
function sharePercent(shares,data=getOwnership()){return data.total?shares*100/data.total:0;}
function frNumber(value,digits=0){return Number(value).toLocaleString('fr-FR',{minimumFractionDigits:digits,maximumFractionDigits:digits});}
function money(cents){return (cents/100).toLocaleString('fr-FR',{style:'currency',currency:'EUR'});}
function personInitials(name){return name.split(/\s+/).filter(Boolean).slice(0,2).map(word=>word[0]).join('').toUpperCase();}
let companyPage=1,companyPageSize=6,companyQuery='',companySort='name',associatePage=1,associatePageSize=10;
