function capitalSegments(data=getOwnership()){const segments=data.associates.filter(item=>item.shares>0).slice().sort((a,b)=>b.shares-a.shares).map((item,index)=>({...item,color:ownershipPalette[index%ownershipPalette.length]}));const remainder=data.total-allocatedShares(data);if(remainder>0)segments.push({id:'unallocated',name:'Titres non attribués',shares:remainder,color:'#e6ebdf',unallocated:true});return segments;}
function ownershipDonut(data=getOwnership(),small=false){const segments=capitalSegments(data),circumference=2*Math.PI*70;let offset=0;const circles=segments.map(item=>{const length=data.total?item.shares/data.total*circumference:0;const part=`<circle cx="87" cy="87" r="70" style="stroke:${item.color};stroke-dasharray:${Math.max(0,length-(segments.length>1?2.5:0))} ${circumference};stroke-dashoffset:${-offset}"/>`;offset+=length;return part;}).join('');return `<div class="ownership-donut ${small?'ownership-donut-small':''}" role="img" aria-label="${escapeHTML(segments.map(item=>item.name+' : '+frNumber(sharePercent(item.shares,data),2)+' %').join(', ')||'Aucun titre renseigné')}"><svg class="donut" viewBox="0 0 174 174" aria-hidden="true"><circle class="donut-track" cx="87" cy="87" r="70"/>${circles}</svg><div class="donut-center"><strong>${data.total?frNumber(sharePercent(allocatedShares(data),data),allocatedShares(data)===data.total?0:1)+'<small>%</small>':'—'}</strong><span>${data.total?'du capital attribué':'Capital à renseigner'}</span></div></div>`;}
function associateNavigation(){const data=getOwnership(),equal=data.associates.length>0&&data.associates.every(item=>item.shares===data.associates[0].shares);return `<div class="associate-context"><a href="#societe" class="associate-company-context"><span>${escapeHTML(company.name.charAt(0))}</span><strong>${escapeHTML(company.name)}</strong><small>SIREN ${escapeHTML(company.siren)}</small></a><a href="#societe" class="text-link">Vue de la société ${icon('arrow')}</a></div>${currentCompany.volumeDemo?'<p class="volume-demo-notice">Données de démonstration · '+frNumber(data.associates.length)+' associés · '+(equal?frNumber(data.associates[0].shares)+' titres chacun · '+frNumber(sharePercent(data.associates[0].shares,data),2)+' % du capital':frNumber(data.total)+' titres émis')+'.</p>':''}<div class="associate-workspace-nav associate-volume-nav">${RGSubnav.render({id:'associate-navigation',scope:currentCompany.id,overviewHref:'#associes',items:data.associates.map(item=>({id:item.id,label:item.name,account:item.account,href:'#associes/'+item.id,avatar:personInitials(item.name)})),activeId:associateViewId||''})}${!associateViewId?`<div class="associate-global-search">${icon('search')}<label class="sr-only" for="associate-search">Rechercher un associé</label><input id="associate-search" type="search" value="${escapeHTML(associateQuery)}" placeholder="Rechercher un associé…" autocomplete="off"></div>`:''}</div>`;}

function associates(){const data=getOwnership();if(associateViewId){const selected=data.associates.find(item=>item.id===associateViewId);if(selected)return associateDetail(selected);return associateNavigation()+`<section class="panel empty-state">${icon('users')}<h3>Cette fiche n’est pas disponible.</h3><a class="button" href="#associes">Revenir aux associés</a></section>`;}return `<div class="associates-page">${associateNavigation()}<section class="panel ownership-overview"><div class="ownership-panel-heading"><div><span class="ownership-eyebrow">UNE VUE CLAIRE DE VOTRE ACTIONNARIAT</span><h2>Répartition du capital</h2></div><div><button class="button" data-action="edit-capital">${icon('edit')}Modifier le capital</button><button class="icon-button" data-action="capital-help" aria-label="Comprendre la répartition du capital">${icon('help')}</button></div></div><div class="ownership-overview-content"><div class="ownership-total"><span>Montant du capital</span><strong>${data.total?money(data.total*data.nominalCents):'À renseigner'}</strong><dl><div><dt>Nombre de titres</dt><dd>${frNumber(data.total)}</dd></div><div><dt>Valeur nominale</dt><dd>${money(data.nominalCents)}</dd></div></dl><button class="button button-outline" data-action="export-capital">${icon('download')}Table de capitalisation</button></div><div class="ownership-distribution"><div class="ownership-distribution-heading"><span>${data.associates.length} associé${data.associates.length>1?'s':''}</span><span>${frNumber(data.total)} titres</span></div>${data.associates.length?capitalSegments(data).map(item=>item.unallocated?`<div class="ownership-legend-item unallocated"><i style="background:${item.color}"></i><span><strong>Titres non attribués</strong><small>${frNumber(item.shares)} titres</small></span><b>${frNumber(sharePercent(item.shares),2)} %</b></div>`:`<a class="ownership-legend-item" href="#associes/${item.id}"><i style="background:${item.color}"></i><span><strong>${escapeHTML(item.name)}</strong><small>${frNumber(item.shares)} titres · Compte ${item.account}</small></span><b>${frNumber(sharePercent(item.shares),2)} %</b>${icon('chevron')}</a>`).join(''):'<p class="ownership-zero-copy">Votre actionnariat commence ici.<br>Ajoutez un associé et renseignez le capital de votre société.</p>'}</div><div class="ownership-chart-area">${ownershipDonut(data)}<span>${icon('shield')}${allocatedShares(data)===data.total&&data.total?'Capital entièrement réparti':frNumber(data.total-allocatedShares(data))+' titres à attribuer'}</span></div></div><div class="ownership-overview-foot">${icon('file')}${escapeHTML(data.type)}${data.name?' · '+escapeHTML(data.name):''}<span>Les pourcentages sont calculés à partir des titres détenus.</span></div></section>
<section class="panel associates-table-panel"><div class="shareholder-list-heading"><div><h2>Les associés <span>${data.associates.length}</span></h2><p>Les comptes d’associés et leur participation dans la société.</p></div><button class="button" data-action="export-associates">${icon('download')}Télécharger la liste complète</button></div><div class="shareholders-table-scroll"><table class="shareholders-table"><thead><tr>${associateTableHead('name','Nom / Dénomination')}${associateTableHead('account','N° de compte')}${associateTableHead('shares','Nombre de titres')}${associateTableHead('percent','Part du capital')}<th><span class="sr-only">Voir la fiche</span></th></tr></thead><tbody id="associate-table-body">${associateRows()}</tbody></table></div><div class="shareholder-table-foot"><span id="associate-result-count" role="status">${filteredAssociates().length} associé(s) trouvé(s)</span><span>Total : ${frNumber(allocatedShares(data))} titres attribués</span></div><div id="associate-pagination" class="associates-pagination-wrap">${associatePagination()}</div></section>
<section class="panel securities-table-panel"><div class="shareholder-list-heading"><div><h2>Les titres <span>${ownershipCategories(data).filter(c=>c.quantity).length}</span></h2><p>Les caractéristiques des titres qui composent votre capital.</p></div><div class="securities-search">${icon('search')}<label class="sr-only" for="security-search">Rechercher un type de titres</label><input id="security-search" type="search" placeholder="Rechercher un type de titres…" value="${escapeHTML(securityQuery)}" autocomplete="off"></div></div><div class="shareholders-table-scroll"><table class="shareholders-table securities-table"><thead><tr><th>Type de titres</th><th>Nom des titres</th><th>Nombre de titres émis</th><th><span class="sr-only">Détails</span></th></tr></thead><tbody id="security-table-body">${securityRows()}</tbody></table></div></section></div>`;}
function associateTableHead(key,label){const sorted=associateSort.key===key;return `<th data-associate-column="${key}" aria-sort="${sorted?(associateSort.direction===1?'ascending':'descending'):'none'}"><button data-associate-sort="${key}">${label}<span aria-hidden="true">${sorted?(associateSort.direction===1?'↑':'↓'):'↕'}</span></button></th>`;}
function normalizedSearch(value){return value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();}
function filteredAssociates(){const query=normalizedSearch(associateQuery);return getOwnership().associates.filter(item=>normalizedSearch(item.name+' '+item.account).includes(query)).slice().sort((a,b)=>{const key=associateSort.key;const result=key==='name'?a.name.localeCompare(b.name,'fr'):(key==='account'?a.account-b.account:a.shares-b.shares);return result*associateSort.direction;});}
function associateRows(){const data=getOwnership(),all=filteredAssociates();associatePage=RGCollections.clamp(associatePage,all.length,associatePageSize);const rows=all.slice((associatePage-1)*associatePageSize,associatePage*associatePageSize);return rows.map(item=>`<tr><td><a class="shareholder-person" href="#associes/${item.id}"><span class="shareholder-avatar">${escapeHTML(personInitials(item.name))}</span><span><strong>${escapeHTML(item.name)}</strong><small>${escapeHTML(item.kind)}</small></span></a></td><td><span class="associate-account-number">${String(item.account).padStart(3,'0')}</span></td><td>${frNumber(item.shares)}</td><td><span class="associate-percentage">${frNumber(sharePercent(item.shares,data),2)} %</span><span class="associate-percentage-bar"><i style="width:${sharePercent(item.shares,data)}%"></i></span></td><td><a class="icon-button associate-row-link" href="#associes/${item.id}" aria-label="Voir la fiche de ${escapeHTML(item.name)}">${icon('arrow')}</a></td></tr>`).join('')||`<tr><td colspan="5" class="shareholder-table-empty">${data.associates.length?'Aucun associé ne correspond à votre recherche.':'Aucun associé n’a encore été ajouté à cette société.'}</td></tr>`;}
function securityRows(){const data=getOwnership(),cats=ownershipCategories(data).filter(c=>c.quantity&&normalizedSearch(c.type+' '+c.name).includes(normalizedSearch(securityQuery)));return cats.map(c=>`<tr><td><span class="security-type-label">${icon('file')}${escapeHTML(c.type)}</span></td><td class="security-name">${escapeHTML(c.name)}</td><td>${frNumber(c.quantity)}</td><td><button class="text-link" data-action="security-details">Détails ${icon('arrow')}</button></td></tr>`).join('')||`<tr><td colspan="4" class="shareholder-table-empty">${data.total?'Aucun type de titres ne correspond à votre recherche.':'Aucun titre émis n’a encore été renseigné.'}</td></tr>`;}
function associatePagination(){return RGCollections.render({id:'associates',total:filteredAssociates().length,page:associatePage,pageSize:associatePageSize,sizes:[10,20,50],label:'associés',controls:'associate-table-body'});}
function refreshAssociateTable(){if(!$('#associate-table-body'))return;$('#associate-table-body').innerHTML=associateRows();$('#associate-result-count').textContent=filteredAssociates().length+' associé(s) trouvé(s)';$('#associate-pagination').innerHTML=associatePagination();$$('[data-associate-column]').forEach(el=>{const key=el.dataset.associateColumn,sorted=key===associateSort.key;el.setAttribute('aria-sort',sorted?(associateSort.direction===1?'ascending':'descending'):'none');$('button span',el).textContent=sorted?(associateSort.direction===1?'↑':'↓'):'↕';});}
function validISODate(value){return typeof value==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(value)&&!Number.isNaN(Date.parse(value))&&new Date(value).toISOString().slice(0,10)===value;}
function displayDate(value){return validISODate(value)?value.split('-').reverse().join('/'):'Non renseignée';}
function splitPersonName(value){const parts=String(value||'').trim().split(/\s+/);return {firstname:parts.shift()||'',lastname:parts.join(' ')};}
function normalizeAssociateExtras(row,example=false){const known=example&&String(row.id)==='1'&&String(row.name).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()==='amelien delahaie';const names=row.kind==='Personne morale'?{firstname:'',lastname:''}:splitPersonName(row.name);const text=(key,fallback='',max=250)=>typeof row[key]==='string'?row[key].trim().slice(0,max):fallback;const result={ledgerVersion:1,civility:['Madame','Monsieur'].includes(row.civility)?row.civility:'',firstname:text('firstname',names.firstname,80),lastname:text('lastname',names.lastname,80),usageName:text('usageName','',100),entitySiren:typeof row.entitySiren==='string'&&row.entitySiren.replace(/\D/g,'').length===9?row.entitySiren.replace(/\D/g,''):'',birthDate:typeof row.birthDate==='string'?(validISODate(row.birthDate)?row.birthDate:''):(known?'2009-06-09':''),birthPlace:text('birthPlace',known?'Rennes':'',150),holdingMode:['Nominatif pur','Nominatif administré','Au porteur'].includes(row.holdingMode)?row.holdingMode:(typeof row.holdingMode==='string'?'':known?'Nominatif pur':''),additionalInfo:text('additionalInfo','',600),holdingInfo:text('holdingInfo','',250),invitationDrafted:row.invitationDrafted===true,ledgerRegisterLinked:row.ledgerRegisterLinked===true,operations:[]};const defaults=known?[{number:1,date:'2023-01-11',nature:'Création',type:'Actions ordinaires',name:'Actions ordinaires',acquired:500,cancelled:0,balance:500,observation:''},{number:2,date:'2023-05-15',nature:'Cession de titres',type:'Actions ordinaires',name:'Actions ordinaires',acquired:0,cancelled:250,balance:250,observation:'Cession 2023.'},{number:3,date:'2024-05-22',nature:'Cession de titres',type:'Actions ordinaires',name:'Actions ordinaires',acquired:0,cancelled:1,balance:249,observation:''}]:[];const operations=Array.isArray(row.operations)?row.operations:defaults;let balance=0;for(const op of operations.slice(0,500)){if(!op||!validISODate(op.date)||![op.acquired,op.cancelled,op.balance].every(n=>Number.isSafeInteger(n)&&n>=0)||balance+op.acquired-op.cancelled!==op.balance)break;balance=op.balance;result.operations.push({number:result.operations.length+1,date:op.date,nature:String(op.nature||'').slice(0,100),type:String(op.type||'').slice(0,100),name:String(op.name||'').slice(0,100),acquired:op.acquired,cancelled:op.cancelled,balance,observation:String(op.observation||'').slice(0,300)});}return result;}
function currentAssociate(){return getOwnership().associates.find(item=>item.id===associateViewId);}
function associatePersonalRows(item){if(item.kind==='Indivision')return `<div><dt>Nom de l’indivision</dt><dd>${escapeHTML(item.name)}</dd></div><div><dt>Adresse</dt><dd>${escapeHTML(item.address||'Non renseignée')}</dd></div><div><dt>E-mail</dt><dd>${escapeHTML(item.email||'Non renseigné')}</dd></div>`;const person=item.kind!=='Personne morale';return person?`<div><dt>Civilité</dt><dd>${escapeHTML(item.civility||'Non renseignée')}</dd></div><div><dt>Prénom(s)</dt><dd>${escapeHTML(item.firstname||'Non renseigné')}</dd></div><div><dt>Nom de famille</dt><dd>${escapeHTML(item.lastname||'Non renseigné')}</dd></div><div><dt>Nom d’usage</dt><dd>${escapeHTML(item.usageName||'Non renseigné')}</dd></div><div><dt>Date et lieu de naissance</dt><dd>${item.birthDate?displayDate(item.birthDate):'Non renseignés'}${item.birthPlace?' · '+escapeHTML(item.birthPlace):''}</dd></div><div><dt>Adresse</dt><dd>${escapeHTML(item.address||'Non renseignée')}</dd></div><div><dt>Adresse e-mail</dt><dd>${escapeHTML(item.email||'Non renseignée')}</dd></div>`:`<div><dt>Dénomination</dt><dd>${escapeHTML(item.name)}</dd></div><div><dt>Nature de l’associé</dt><dd>Personne morale</dd></div><div><dt>Adresse du siège</dt><dd>${escapeHTML(item.address||'Non renseignée')}</dd></div><div><dt>Adresse e-mail</dt><dd>${escapeHTML(item.email||'Non renseignée')}</dd></div>`;}
function associateDetail(item){const data=getOwnership();return `<div class="associates-page associate-full-detail">${associateNavigation()}<section class="associate-profile-hero"><div class="associate-profile-identity"><span class="associate-profile-monogram">${escapeHTML(personInitials(item.name))}</span><div><div class="ownership-eyebrow">COMPTE D’ASSOCIÉ N° ${String(item.account).padStart(3,'0')}</div><h2>${escapeHTML(item.name)}</h2><span class="badge">${escapeHTML(item.kind)}</span></div></div><div class="associate-profile-numbers"><div><strong>${frNumber(item.shares)}</strong><span>Titres détenus</span></div><div><strong>${frNumber(sharePercent(item.shares,data),2)}<small> %</small></strong><span>du capital</span></div></div><div class="associate-authentication"><span>Authentification de l’associé<button class="icon-button" data-action="associate-auth-help" aria-label="À propos de l’authentification">${icon('help')}</button></span><strong><i></i>À authentifier</strong><button class="button" data-action="associate-invite">${icon('users')}Inviter l’associé</button>${item.invitationDrafted?'<small>Brouillon d’invitation préparé · Aucun envoi</small>':''}</div><div class="associate-profile-footer"><span>${icon('shield')}La participation et l’authentification sont suivies séparément.</span><button class="button" data-action="associate-certificate">${icon('file')}Attestation de participation</button></div></section>
<div class="associate-personal-grid"><section class="panel associate-personal-card"><div class="panel-heading"><div class="panel-title">${icon('users')}<h3>Informations de l’associé</h3></div><button class="text-link" data-associate-edit="${item.id}">${icon('edit')}Modifier</button></div><dl class="associate-detail-info">${associatePersonalRows(item)}</dl></section><section class="panel associate-holdings-card"><div class="panel-heading"><div class="panel-title">${icon('file')}<h3>Titres détenus</h3></div><span>${frNumber(item.shares)} titres</span></div><div class="associate-holdings-scroll"><table><thead><tr><th>Nature des titres</th><th>Nombre</th><th>Informations</th></tr></thead><tbody>${capitalAssociateHoldings(item,data).filter(h=>h.quantity).map(h=>`<tr><td>${escapeHTML(ownershipCategories(data).find(c=>c.id===h.categoryId)?.name||data.type)}</td><td>${frNumber(h.quantity)}</td><td>${escapeHTML(item.holdingInfo||'Aucune')}</td></tr>`).join('')}${item.warrants?`<tr><td>Bons · hors capital</td><td>${frNumber(item.warrants)}</td><td>Situation déclarée</td></tr>`:''}</tbody></table></div><div class="associate-holdings-footer"><span>Valeur nominale détenue</span><strong>${money(item.shares*data.nominalCents)}</strong></div><button class="associate-account-anchor" data-action="associate-scroll-account">Consulter le compte d’associé ${icon('arrow')}</button></section></div>
${associatePaperSection(item)}</div>`;}
function paperCartouche(title,body,edit=false){return `<section class="paper-cartouche"><h3>${title}${edit?`<button class="paper-only-control" data-action="associate-account-settings" aria-label="Modifier ${title.toLowerCase()}">${icon('edit')}</button>`:''}</h3><div>${body}</div></section>`;}
function associatePaper(item){const last=item.operations.at(-1),balance=last?last.balance:item.shares,mismatch=!!last&&balance!==item.shares;return `<article class="ledger-sheet" id="associate-ledger" aria-label="Compte d’associé papier de ${escapeHTML(item.name)}"><header class="ledger-document-header">${paperCartouche('IDENTITÉ DE LA SOCIÉTÉ',`<dl><div><dt>Dénomination</dt><dd>${escapeHTML(company.name)}</dd></div><div><dt>Numéro SIREN</dt><dd>${escapeHTML(company.siren)}</dd></div></dl>`)}<div class="ledger-document-title"><span>REGISTRE DE TITRES · FEUILLET INDIVIDUEL</span><h2>Compte d’associé</h2><p>${frNumber(balance)} <span>titres au compte</span></p></div><section class="paper-account-number"><h3>COMPTE</h3><div><strong>N° ${item.account}</strong><button class="paper-only-control" data-action="associate-account-settings" aria-label="Modifier le numéro de compte">${icon('edit')}</button></div></section></header><div class="ledger-document-body"><aside class="ledger-identity-column">${paperCartouche('IDENTITÉ DU TITULAIRE',`<p class="paper-holder-name">${escapeHTML(item.kind!=='Personne physique'?item.name:[item.firstname,item.lastname].filter(Boolean).join('\n')||item.name).replace(/\n/g,'<br>')}</p>`)}${paperCartouche('MODE DE DÉTENTION',`<p>${escapeHTML(item.holdingMode||'Non renseigné')}</p>`,true)}${paperCartouche('INFORMATION COMPLÉMENTAIRE',`<p class="paper-additional-info">${escapeHTML(item.additionalInfo||'Non renseignée')}</p>`,true)}</aside><div class="ledger-operations"><table class="paper-operations-table"><caption class="sr-only">Opérations et soldes du compte d’associé n° ${item.account}</caption><colgroup><col style="width:4%"><col style="width:10%"><col style="width:12%"><col style="width:15%"><col style="width:14%"><col style="width:8%"><col style="width:8%"><col style="width:10%"><col style="width:19%"></colgroup><thead><tr><th colspan="3" scope="colgroup">OPÉRATION</th><th rowspan="2" scope="col">NATURE DES TITRES</th><th rowspan="2" scope="col">NOM DES TITRES</th><th colspan="3" scope="colgroup">NOMBRE DE TITRES</th><th rowspan="2" scope="col">OBSERVATION</th></tr><tr><th scope="col">N°</th><th scope="col">DATE</th><th scope="col">NATURE</th><th scope="col">ACQUIS</th><th scope="col">RADIÉS</th><th scope="col">SOLDE</th></tr></thead><tbody>${item.operations.map(op=>`<tr><td>${op.number}</td><td>${displayDate(op.date)}</td><td>${escapeHTML(op.nature)}</td><td>${escapeHTML(op.type)}</td><td>${escapeHTML(op.name||'—')}</td><td>${frNumber(op.acquired)}</td><td>${frNumber(op.cancelled)}</td><td class="paper-running-balance"><span>${frNumber(op.balance)}</span><i class="paper-security-code code-action" title="Actions">A</i></td><td>${escapeHTML(op.observation)}</td></tr>`).join('')||'<tr><td colspan="9" class="paper-no-operations">Aucune opération n’est renseignée pour ce compte. Le nombre de titres détenus ne constitue pas, à lui seul, un historique de mouvements.</td></tr>'}</tbody></table><div class="paper-security-legend"><span><i class="paper-security-code code-action">A</i>Actions</span><span><i class="paper-security-code code-warrant">B</i>Bons</span><span><i class="paper-security-code code-bond">O</i>Obligations</span></div><div class="paper-balance-summary"><span>${last?'Solde au dernier mouvement du '+displayDate(last.date):'Situation déclarée · Aucun historique renseigné'}</span><strong>${frNumber(balance)} titres</strong></div>${mismatch?`<p class="paper-reconciliation">Écart à vérifier : le dernier solde enregistré est de ${frNumber(balance)} titres ; la fiche indique ${frNumber(item.shares)} titres. L’historique doit être complété.</p>`:''}</div></div><footer class="ledger-document-footer"><span>Registre Général · Données de démonstration · Sans valeur juridique</span><span>Compte n° ${item.account} · Feuillet 1 / 1</span></footer></article>`;}
function associatePaperSection(item){const last=item.operations.at(-1);return `<section class="associate-ledger-area" id="compte-associe"><div class="associate-ledger-toolbar"><div><span class="ownership-eyebrow">LE FEUILLET DE VOTRE ASSOCIÉ</span><h2>Compte d’associé</h2><p>Les identités, les opérations et les soldes réunis sur un même document.</p></div><div><button class="button" data-action="associate-account-download">${icon('download')}Télécharger le compte</button><button class="button" data-action="associate-account-print">${icon('file')}Imprimer / PDF</button></div></div>${last&&last.balance!==item.shares?`<div class="account-reconciliation-note" role="status">${icon('help')}Le solde du feuillet (${frNumber(last.balance)} titres) diffère de la fiche (${frNumber(item.shares)} titres). Aucune opération n’a été inventée pour combler cet écart.</div>`:''}<p class="ledger-mobile-hint">Faites défiler le feuillet horizontalement pour lire toutes les colonnes.</p><div class="ledger-scroll"><div class="ledger-paper-stack">${associatePaper(item)}</div></div></section>`;}
function associateOptionalInput(name,label,value='',type='text',extra=''){return `<div class="form-field"><label for="associate-${name}">${label}</label><input id="associate-${name}" name="${name}" type="${type}" value="${escapeHTML(value)}" maxlength="150" ${extra}></div>`;}
function editAssociate(id=null){const data=getOwnership();if(data.categories){startCapitalSetup();capitalSetup.step=3;capitalSetup.visited=3;const found=id?capitalSetup.people.find(p=>p.id===id):null;capitalSetup.editor=found?JSON.parse(JSON.stringify(found)):id?null:{id:String(Math.max(0,...capitalSetup.people.map(p=>Number(p.id)))+1),kind:'Personne physique',name:'',shares:0,warrants:0,holdings:[],existing:false};showCapitalSetup();return;}const item=id?data.associates.find(row=>row.id===id):null;if(id&&!item)return;const values=item||{...normalizeAssociateExtras({name:'',id:'',kind:'Personne physique'}),name:'',kind:'Personne physique',shares:0,email:'',address:''},person=values.kind!=='Personne morale',available=data.total-allocatedShares(data)+(item?.shares||0);const today=new Date().toLocaleDateString('sv-SE',{timeZone:'Europe/Paris'});modal(item?'Modifier la fiche de l’associé':'Ajouter un associé',`<p class="modal-description">${item?'Complétez les informations du titulaire et ses coordonnées.':'Créez un compte d’associé pour '+escapeHTML(company.name)+'.'}</p><form id="associate-form" data-associate-id="${item?.id||''}"><div class="form-field"><label for="associate-kind">Nature de l’associé</label><select id="associate-kind" name="kind"><option ${person?'selected':''}>Personne physique</option><option ${!person?'selected':''}>Personne morale</option></select></div><fieldset class="associate-person-fields" ${!person?'hidden disabled':''}><legend>Identité du titulaire</legend><div class="form-field"><label for="associate-civility">Civilité</label><select id="associate-civility" name="civility"><option value="">Non renseignée</option><option ${values.civility==='Madame'?'selected':''}>Madame</option><option ${values.civility==='Monsieur'?'selected':''}>Monsieur</option></select></div><div class="form-row">${associateOptionalInput('firstname','Prénom(s)',values.firstname,'text','required')}${associateOptionalInput('lastname','Nom de famille',values.lastname,'text','required')}</div>${associateOptionalInput('usageName','Nom d’usage · facultatif',values.usageName)}<div class="form-row">${associateOptionalInput('birthDate','Date de naissance · facultatif',values.birthDate,'date',`max="${today}"`)}${associateOptionalInput('birthPlace','Lieu de naissance · facultatif',values.birthPlace)}</div></fieldset><fieldset class="associate-entity-fields" ${person?'hidden disabled':''}><legend>Identité de la personne morale</legend>${associateOptionalInput('name','Dénomination',values.name,'text','required')}</fieldset>${field('shares','Nombre de titres détenus',values.shares,'number',`min="0" max="${available}" step="1"`)}${associateOptionalInput('email','Adresse e-mail · facultatif',values.email,'email')}<div class="form-field"><label for="associate-address">Adresse · facultatif</label><textarea id="associate-address" name="address" maxlength="250">${escapeHTML(values.address||'')}</textarea></div><p class="demo-note">${frNumber(available)} titres disponibles pour ce compte. L’enregistrement ne réalise aucune vérification d’identité et ne crée aucun mouvement juridique. Les informations restent dans ce navigateur.</p><div id="ownership-form-status" class="ownership-form-status" role="status"></div>${formActions(item?'Enregistrer la fiche':'Ajouter l’associé')}</form>`);}
function saveAssociateForm(form){const values=new FormData(form),data=getOwnership(),id=form.dataset.associateId,item=data.associates.find(row=>row.id===id),kind=String(values.get('kind')),text=key=>String(values.get(key)||'').trim(),firstname=kind==='Personne physique'?text('firstname'):'',lastname=kind==='Personne physique'?text('lastname'):'',name=kind==='Personne morale'?text('name'):[firstname,lastname].join(' ').trim(),shares=Number(values.get('shares')),available=data.total-allocatedShares(data)+(item?.shares||0);if(!name||(kind==='Personne physique'&&(!firstname||!lastname))||!Number.isSafeInteger(shares)||shares<0||shares>available){$('#ownership-form-status').textContent='Complétez l’identité et indiquez un nombre entier de titres, sans dépasser '+frNumber(available)+' titres.';return;}const nextAccount=Math.max(0,...data.associates.map(row=>row.account))+1,nextId=Math.max(0,...data.associates.map(row=>Number(row.id)))+1;const extras=item?normalizeAssociateExtras(item,currentCompany.example):normalizeAssociateExtras({id:String(nextId),name,kind});const value={...extras,id:item?.id||String(nextId),account:item?.account||nextAccount,name:name.slice(0,120),kind,shares,email:text('email').slice(0,150),address:text('address').slice(0,250),firstname:firstname.slice(0,80),lastname:lastname.slice(0,80),civility:kind==='Personne physique'?text('civility'):'',usageName:kind==='Personne physique'?text('usageName').slice(0,100):'',birthDate:kind==='Personne physique'&&validISODate(text('birthDate'))?text('birthDate'):'',birthPlace:kind==='Personne physique'?text('birthPlace').slice(0,150):''};if(item)Object.assign(item,value);else data.associates.push(value);const saved=persistWorkspace();$('#modal').close();render();toast(saved?'La fiche de l’associé a été enregistrée.':'Modification conservée pour cette session ; stockage indisponible.');}
function editAssociateAccount(){const item=currentAssociate();if(!item)return;modal('Paramètres du compte d’associé',`<p class="modal-description">Les cartouches du feuillet de ${escapeHTML(item.name)}.</p><form id="associate-account-form">${field('account','Numéro de compte',item.account,'number','min="1" max="999999" step="1"')}<div class="form-field"><label for="holding-mode">Mode de détention</label><select id="holding-mode" name="holdingMode"><option value="">Non renseigné</option>${['Nominatif pur','Nominatif administré','Au porteur'].map(mode=>`<option ${item.holdingMode===mode?'selected':''}>${mode}</option>`).join('')}</select></div><div class="form-field"><label for="account-additional">Information complémentaire</label><textarea id="account-additional" name="additionalInfo" maxlength="600">${escapeHTML(item.additionalInfo)}</textarea></div><div class="form-field"><label for="account-holding-info">Informations sur les titres détenus</label><textarea id="account-holding-info" name="holdingInfo" maxlength="250">${escapeHTML(item.holdingInfo)}</textarea></div><p class="demo-note">Ces modifications concernent les cartouches du compte. Elles ne modifient pas l’historique de ses opérations.</p><div class="ownership-form-status" id="account-form-status" role="status"></div>${formActions('Enregistrer le compte')}</form>`);}
function saveAssociateAccount(form){const item=currentAssociate();if(!item)return;const values=new FormData(form),account=Number(values.get('account'));if(!Number.isSafeInteger(account)||account<1||account>999999||getOwnership().associates.some(other=>other.id!==item.id&&other.account===account)){$('#account-form-status').textContent='Choisissez un numéro de compte unique, entre 1 et 999 999.';return;}item.account=account;item.holdingMode=String(values.get('holdingMode'));item.additionalInfo=String(values.get('additionalInfo')).trim().slice(0,600);item.holdingInfo=String(values.get('holdingInfo')).trim().slice(0,250);const saved=persistWorkspace();$('#modal').close();render();toast(saved?'Le compte d’associé a été mis à jour.':'Compte modifié pour cette session ; stockage indisponible.');}
function inviteAssociate(){const item=currentAssociate();if(!item)return;modal('Inviter l’associé à s’authentifier',`<p class="modal-description">Préparez une invitation pour ${escapeHTML(item.name)}.</p><form id="associate-invitation-form">${field('email','Adresse e-mail du destinataire',item.email,'email','maxlength="150"')}<div class="associate-invitation-preview"><strong>Invitation à votre espace associé</strong><p>Vous êtes invité à retrouver votre compte d’associé de ${escapeHTML(company.name)} et à compléter votre authentification.</p></div><p class="demo-note">Démonstration : seul un brouillon est téléchargé. Aucun e-mail n’est envoyé et l’associé n’est pas marqué comme authentifié.</p>${formActions('Préparer l’invitation')}</form>`);}
function prepareAssociateInvitation(form){const item=currentAssociate();if(!item)return;const email=String(new FormData(form).get('email')).trim();download('invitation-associe-brouillon.txt',`BROUILLON DE DÉMONSTRATION — AUCUN ENVOI\n\nDestinataire : ${email}\nAssocié : ${item.name}\nSociété : ${company.name}\nCompte n° ${item.account}\n\nVous êtes invité à retrouver votre compte d’associé et à compléter votre authentification.\n\nAucun lien d’authentification réel n’est généré dans cette maquette.\n`);item.invitationDrafted=true;persistWorkspace();$('#modal').close();render();toast('Brouillon préparé. Aucun e-mail n’a été envoyé.');}
function associateAuthenticationHelp(){modal('Authentification de l’associé',`<p class="modal-description">Le nombre de titres détenus et la vérification de l’identité de leur titulaire sont deux informations distinctes.</p><p class="demo-note">L’authentification n’est pas réalisée dans cette maquette. Préparer une invitation ne valide pas l’identité de l’associé et ne lui accorde aucun accès réel.</p>`);}
function certificatePreview(){const item=currentAssociate();if(!item)return;modal('Attestation de participation',`<div class="certificate-preview"><span>SPÉCIMEN DE DÉMONSTRATION</span><h3>${escapeHTML(item.name)}</h3><p>${escapeHTML(company.name)} · SIREN ${escapeHTML(company.siren)}</p><strong>${frNumber(item.shares)} titres</strong><p>${frNumber(sharePercent(item.shares),2)} % du capital · Compte n° ${item.account}</p></div><p class="demo-note">Ce document est un exemple sans valeur juridique, non signé et non certifié. Les données doivent être vérifiées avant l’émission d’une attestation officielle.</p><button class="button button-primary certificate-download" data-action="associate-certificate-download">${icon('download')}Télécharger le spécimen HTML</button>`);}
function downloadCertificate(){const item=currentAssociate();if(!item)return;const date=new Intl.DateTimeFormat('fr-FR',{timeZone:'Europe/Paris',dateStyle:'long'}).format(new Date());const html=`<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Spécimen d’attestation de participation</title><style>body{margin:0;padding:40px;background:#f3f4ee;color:#3d5343;font:15px Georgia,serif}.document{max-width:760px;margin:auto;background:white;border:1px solid #dce3d3;padding:60px;position:relative}.brand{font:16px Arial,sans-serif;color:#42674a;border-bottom:1px solid #dfe7d8;padding-bottom:24px}.specimen{font:10px Arial,sans-serif;letter-spacing:2px;color:#9da88e;margin:40px 0 20px}h1{font-weight:400;font-size:34px;line-height:1.3}p{line-height:2}dl>div{padding:14px 0;border-bottom:1px solid #e7ecdf;display:flex;justify-content:space-between;gap:30px}dt{color:#97a48a}dd{margin:0;text-align:right}.notice{margin-top:40px;font:11px/1.8 Arial,sans-serif;color:#9ba88c}.date{font-size:12px;color:#9ba88c;margin-top:30px}@media print{@page{size:A4;margin:18mm}body{padding:0;background:white}.document{padding:0;border:0;max-width:none}}</style></head><body><article class="document"><div class="brand">Registre Général</div><div class="specimen">SPÉCIMEN · SANS VALEUR JURIDIQUE</div><h1>Attestation de participation</h1><p>Présentation illustrative de la participation de <strong>${escapeHTML(item.name)}</strong> dans la société <strong>${escapeHTML(company.name)}</strong>.</p><dl><div><dt>SIREN de la société</dt><dd>${escapeHTML(company.siren)}</dd></div><div><dt>Compte d’associé</dt><dd>N° ${item.account}</dd></div><div><dt>Nature des titres</dt><dd>${escapeHTML(getOwnership().type)}</dd></div><div><dt>Titres détenus</dt><dd>${frNumber(item.shares)}</dd></div><div><dt>Part du capital</dt><dd>${frNumber(sharePercent(item.shares),2)} %</dd></div></dl><p class="date">Spécimen préparé le ${date}.</p><p class="notice">Document de démonstration non signé et non certifié. Il ne constitue pas une attestation officielle, ne prouve pas une authentification et ne remplace pas la vérification des registres.</p></article></body></html>`;download('attestation-participation-specimen.html',html,'text/html;charset=utf-8');}
function downloadAssociateAccount(){const item=currentAssociate(),paper=$('#associate-ledger');if(!item||!paper)return;const sheet=[...document.styleSheets].find(style=>style.ownerNode?.hasAttribute('data-ledger-style'));let css='';try{css=[...sheet.cssRules].map(rule=>rule.cssText).join('\n');}catch{toast('Le style du document est indisponible. Rechargez la page avant de télécharger.');return;}const clone=paper.cloneNode(true);clone.querySelectorAll('button,.paper-only-control').forEach(el=>el.remove());const html=`<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Compte d’associé n° ${item.account} — ${escapeHTML(item.name)}</title><style>${css}\nbody.ledger-export{margin:0;padding:30px;background:#f0f2ea;font-family:Arial,sans-serif}.ledger-export .ledger-sheet{max-width:1200px;margin:auto}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}</style></head><body class="ledger-export print-associate-ledger">${clone.outerHTML}</body></html>`;download('compte-associe-'+item.account+'.html',html,'text/html;charset=utf-8');}
function printAssociateAccount(){if(!$('#associate-ledger'))return;document.body.classList.add('print-associate-ledger');window.print();}

function editCapital(){startCapitalSetup();}
function securityDetails(){const data=getOwnership();modal('Caractéristiques des titres',`${ownershipCategories(data).filter(c=>c.quantity).map(c=>`<section class="cs-review-category"><h3>${escapeHTML(c.name)}</h3><dl class="security-detail-list"><div><dt>Type de titres</dt><dd>${escapeHTML(c.type)}</dd></div><div><dt>Nombre émis</dt><dd>${frNumber(c.quantity)}</dd></div><div><dt>Valeur nominale</dt><dd>${money(data.nominalCents)}</dd></div><div><dt>Droit de vote</dt><dd>${c.votingRights?'Oui · coefficient '+Number(c.votingCoefficient).toLocaleString('fr-FR',{maximumFractionDigits:6}):'Non'}</dd></div><div><dt>Dividende prioritaire</dt><dd>${c.priorityDividend?'Oui':'Non'}</dd></div></dl></section>`).join('')}<button class="button security-edit-button" data-action="edit-capital">${icon('edit')}Renseigner le capital</button>`);}
function csvCell(value){let text=String(value??'');if(typeof value==='string'&&/^[=+@\-\t\r]/.test(text))text="'"+text;return '"'+text.replace(/"/g,'""')+'"';}
function downloadCapital(){const data=getOwnership();const rows=[['Table de capitalisation',company.name],['SIREN',company.siren],['Capital social (EUR)',data.total*data.nominalCents/100],['Titres émis',data.total],['Valeur nominale (EUR)',data.nominalCents/100],[],['N° de compte','Nom / Dénomination','Nombre de titres','Pourcentage du capital','Valeur nominale détenue (EUR)'],...data.associates.map(item=>[item.account,item.name,item.shares,frNumber(sharePercent(item.shares,data),2)+' %',item.shares*data.nominalCents/100]),['','Titres non attribués',data.total-allocatedShares(data),frNumber(sharePercent(data.total-allocatedShares(data),data),2)+' %','']];download('table-capitalisation.csv','\uFEFF'+rows.map(row=>row.map(csvCell).join(';')).join('\n'),'text/csv;charset=utf-8');}
function downloadAssociates(){const rows=[['Nom / Dénomination','Nature','N° de compte','Nombre de titres','Pourcentage du capital','Adresse e-mail','Adresse'],...getOwnership().associates.map(item=>[item.name,item.kind,item.account,item.shares,frNumber(sharePercent(item.shares),2)+' %',item.email,item.address])];download('liste-associes.csv','\uFEFF'+rows.map(row=>row.map(csvCell).join(';')).join('\n'),'text/csv;charset=utf-8');}
function saveCapitalForm(form){const values=new FormData(form),data=getOwnership(),total=Number(values.get('total')),nominal=Number(values.get('nominal')),cents=Math.round(nominal*100);if(!Number.isSafeInteger(total)||total<allocatedShares(data)||total>100000000||cents<1||!Number.isSafeInteger(total*cents)||Math.abs(nominal*100-cents)>0.00001){$('#ownership-form-status').textContent='Vérifiez le nombre de titres et la valeur nominale. Le total doit couvrir les titres déjà attribués.';return;}data.total=total;data.nominalCents=cents;data.type=String(values.get('type'));data.name=String(values.get('name')).trim().slice(0,100);const saved=persistWorkspace();$('#modal').close();render();toast(saved?'Le capital a été mis à jour.':'Capital modifié pour cette session ; stockage indisponible.');}
function titles(){return operationViewId?renderOperationDetail(operationViewId):renderTitleRegister();}
function decisions(){return renderDecisionRegister();}
function personnel(){return renderPersonnelRegister();}
function documentView(){if(!currentCompany.example)return emptyCompanyView('Documents sociaux','Les documents de cette société.','upload','Ajouter un document');return `<div class="alternate-view">${sectionIntro('Documents sociaux','Vos documents essentiels, organisés et accessibles.',`<button class="button button-primary" data-action="upload">${icon('plus')}Ajouter un document</button>`)}<section class="panel"><div class="table-scroll"><table class="data-table"><thead><tr><th>Document</th><th>Catégorie</th><th>Date</th><th><span class="sr-only">Action</span></th></tr></thead><tbody>${documents.map((doc,index)=>`<tr><td><span class="document-name">${icon('file')}${escapeHTML(doc.name)}</span></td><td>${escapeHTML(doc.type)}</td><td>${escapeHTML(doc.date)}</td><td><button class="icon-button" data-document="${index}" aria-label="Télécharger ${escapeHTML(doc.name)}">${icon('download')}</button></td></tr>`).join('')}</tbody></table></div><div class="panel-foot">${icon('shield')}Les téléchargements contiennent des données de démonstration au format texte.</div></section></div>`;}
function procedures(){if(!currentCompany.example)return emptyCompanyView('Mes procédures','Les formalités de cette société.','new-procedure','Nouvelle procédure');return `<div class="alternate-view">${sectionIntro('Mes procédures','Gardez le cap sur vos formalités en cours.',`<button class="button button-primary" data-action="new-procedure">${icon('plus')}Nouvelle procédure</button>`)}<div class="procedure-list"><section class="panel procedure-row"><span class="action-icon">${icon('download')}</span><div class="procedure-info"><strong>Dépôt des comptes annuels</strong><p>Exercice 2025 · Dossier de démonstration</p></div><span class="badge orange">À compléter</span><button class="button" data-action="accounts">Reprendre ${icon('arrow')}</button></section><section class="panel procedure-row"><span class="action-icon">${icon('file')}</span><div class="procedure-info"><strong>Publication d’une annonce légale</strong><p>Modification de société · Brouillon</p></div><span class="badge orange">Brouillon</span><button class="button" data-action="announcement">Reprendre ${icon('arrow')}</button></section></div></div>`;}
function administrationPreferences(){return `<div class="alternate-view">${sectionIntro('Administration','Personnalisez le suivi de votre société.')}<section class="panel"><div class="panel-heading"><div class="panel-title">${icon('settings')}<h3>Préférences de l’espace</h3></div></div><div class="settings-list"><div class="setting-row"><div><strong>Rappels des échéances</strong><p>Recevoir les rappels liés à vos obligations juridiques.</p></div><button class="toggle" role="switch" aria-label="Rappels des échéances" aria-checked="${settings.reminders}" data-setting="reminders"></button></div><div class="setting-row"><div><strong>Récapitulatif mensuel</strong><p>Un point mensuel sur l’activité de votre espace.</p></div><button class="toggle" role="switch" aria-label="Récapitulatif mensuel" aria-checked="${settings.digest}" data-setting="digest"></button></div><div class="setting-row"><div><strong>Informations de la société</strong><p>Mettre à jour les coordonnées et l’activité.</p></div><button class="button" data-action="edit">Modifier</button></div></div><div class="panel-foot">${icon('shield')}Préférences de démonstration, sans envoi d’e-mail.</div></section></div>`;}
function personalDashboard(){const count=unreadCount();return `${orgContextBanner()}<section class="personal-welcome"><div><span class="welcome-tag">${icon('spark')}VOTRE ESPACE PERSONNEL</span><h2>Tout commence par<br>une vue d’ensemble<span>.</span></h2><p>Vos sociétés, leurs actualités et vos prochaines étapes.<br>L’essentiel est ici, pour avancer l’esprit libre.</p><div class="welcome-profile"><span class="avatar">${escapeHTML(initials())}</span><span><strong>${escapeHTML(fullName())}</strong><small>Votre espace Registre Général</small></span></div></div><div class="welcome-art" aria-hidden="true"><div class="welcome-orbit"></div><div class="welcome-paper back"></div><div class="welcome-paper front"><span>VOTRE QUOTIDIEN, PLUS CLAIR</span><strong>${String(orgCompaniesInContext().length).padStart(2,'0')}<small> société${orgCompaniesInContext().length>1?'s':''}</small></strong><div>${icon('check')}Chaque chose à sa place.</div><i></i><i></i></div><span class="welcome-art-badge">${icon('shield')}Un espace pour tout retrouver.</span></div></section>
<section class="personal-stats" aria-label="Votre espace en chiffres"><article><span class="personal-stat-icon">${icon('building')}</span><div><strong>${String(orgCompaniesInContext().length).padStart(2,'0')}</strong><span>Société${orgCompaniesInContext().length>1?'s':''} ajoutée${orgCompaniesInContext().length>1?'s':''}</span></div><a href="#mes-societes" aria-label="Voir mes sociétés">${icon('arrow')}</a></article><article><span class="personal-stat-icon">${icon('bell')}</span><div><strong>${String(count).padStart(2,'0')}</strong><span>Notification${count>1?'s':''} à lire</span></div><a href="#notifications" aria-label="Voir mes notifications">${icon('arrow')}</a></article><article><span class="personal-stat-icon">${icon('clock')}</span><div><strong>${orgCompaniesInContext().some(c=>c.example)?'02':'00'}</strong><span>Procédures en cours</span></div><button data-action="all-procedures" aria-label="Voir les procédures">${icon('arrow')}</button></article></section>
<div class="personal-grid"><section class="my-companies" id="mes-societes"><div class="dashboard-section-heading"><div><h2>Mes sociétés <span>${orgCompaniesInContext().length}</span></h2><p>Choisissez une société pour retrouver son espace.</p></div><button class="text-link" data-action="add-company">${icon('plus')}Ajouter</button></div><div class="companies-toolbar"><div>${icon('search')}<label class="sr-only" for="company-filter">Rechercher dans mes sociétés</label><input id="company-filter" type="search" value="${escapeHTML(companyQuery)}" placeholder="Rechercher une société, un SIREN…" autocomplete="off"></div><label class="sr-only" for="company-sort">Trier les sociétés</label><select id="company-sort"><option value="name" ${companySort==='name'?'selected':''}>Nom : A → Z</option><option value="recent" ${companySort==='recent'?'selected':''}>Dernière ajoutée</option></select></div>${orgDashboardFilters()}<div class="company-card-grid" id="company-card-grid">${companyCards()}</div><div id="company-pagination">${companyPagination()}</div><div id="company-filter-status" role="status" class="sr-only"></div></section><aside class="dashboard-right"><section class="panel personal-notifications"><div class="panel-heading"><div class="panel-title">${icon('bell')}<h3>Mes notifications</h3><span class="unread-label">${count}</span></div><a class="text-link" href="#notifications">Tout voir ${icon('arrow')}</a></div>${notificationList(true)}${count?'<button class="notification-mark-all" data-action="read-all">Tout marquer comme lu '+icon('check')+'</button>':''}</section><section class="dashboard-tip"><span>${icon('spark')}LE BON RÉFLEXE</span><h3>Une société de plus ?<br>Un espace déjà prêt.</h3><p>Ajoutez une société et retrouvez ses informations au même endroit.</p><button class="text-link" data-action="add-company">Ajouter une société ${icon('arrow')}</button></section></aside></div><section class="panel personal-activity"><div class="panel-heading"><div class="panel-title">${icon('clock')}<h3>Dans votre espace</h3></div><span>Votre organisation, en un coup d’œil.</span></div><div class="personal-activity-items"><div><span class="timeline-symbol">${icon('building')}</span><p><strong>${orgCompaniesInContext().length} société${orgCompaniesInContext().length>1?'s':''} dans votre espace</strong><small>Chaque société dispose de sa propre fiche et de ses registres.</small></p></div><div><span class="timeline-symbol">${icon('users')}</span><p><strong>Un profil pour vous retrouver</strong><small>Vos informations personnelles sont accessibles dans Mon compte.</small></p><a href="#compte" class="text-link">Mon compte ${icon('arrow')}</a></div></div></section>`;}
function filteredCompanies(){const normalize=value=>value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/\s/g,'');let entries=orgCompaniesInContext().filter(entry=>(orgUI.plan==='all'||orgLink(entry.id)?.plan===orgUI.plan)&&(orgUI.responsible==='all'||orgUI.responsible==='none'&&!orgLink(entry.id)?.responsibles.length||orgLink(entry.id)?.responsibles.includes(orgUI.responsible))).filter(entry=>normalize(entry.data.name+' '+entry.data.siren).includes(normalize(companyQuery)));return companySort==='recent'?entries.slice().reverse():entries.slice().sort((a,b)=>a.data.name.localeCompare(b.data.name,'fr'));}
function companyPagination(){return RGCollections.render({id:'companies',total:filteredCompanies().length,page:companyPage,pageSize:companyPageSize,sizes:[6,12,24],label:'sociétés',controls:'company-card-grid'});}
function companyCards(){const all=filteredCompanies();companyPage=RGCollections.clamp(companyPage,all.length,companyPageSize);const entries=all.slice((companyPage-1)*companyPageSize,companyPage*companyPageSize);return entries.map(entry=>`<article class="workspace-company-card"><div class="workspace-company-top"><span class="company-tile-monogram">${escapeHTML(entry.data.name.charAt(0))}</span><span class="badge ${entry.example?'':'orange'}">${entry.demoFixture?'Société fictive':entry.volumeDemo?'Démonstration':entry.example?'Espace actif':'À compléter'}</span><button class="icon-button" data-company-open="${entry.id}" aria-label="Ouvrir ${escapeHTML(entry.data.name)}">${icon('arrow')}</button></div><h3>${escapeHTML(entry.data.name)}</h3>${orgCompanyMetaHTML(entry)}<p class="workspace-company-form">${escapeHTML(entry.data.form)}</p><p class="workspace-company-siren">SIREN ${escapeHTML(entry.data.siren)}</p><p class="workspace-company-address">${icon('pin')}${escapeHTML(entry.data.city)}</p><div class="workspace-company-bottom"><span>${icon('file')}${entry.demoFixture?'Données de démonstration':entry.example?'Registres de démonstration':'Fiche à compléter'}</span><button class="text-link" data-company-open="${entry.id}">Accéder à la société ${icon('arrow')}</button></div></article>`).join('')||'<div class="company-filter-empty">Aucune société ne correspond à votre recherche.</div>'; }
function notificationList(compact=false){return `<div class="workspace-notifications-list">${organizationNotifications().map(item=>{const entry=companies.find(c=>c.id===item.companyId),read=notificationRead.includes(item.id);return `<article class="workspace-notification ${read?'is-read':''}"><span class="notification-type">${icon(item.icon)}</span><div><span class="notification-company">${escapeHTML(entry.data.name)} ${!read?'<i aria-label="Non lue"></i>':''}</span><h3>${escapeHTML(item.title)}</h3><p>${escapeHTML(item.text)}</p><div class="workspace-notification-bottom"><time>${item.date}</time><button class="text-link" data-notification-open="${item.id}">Voir ${icon('arrow')}</button>${!read&&!compact?`<button class="text-link" data-notification-read="${item.id}">Marquer comme lue</button>`:''}</div></div></article>`;}).join('')||'<div class="empty-state">'+icon('bell')+'<h3>Tout est calme.</h3><p>Les nouvelles de vos sociétés apparaîtront ici.</p></div>'}</div>`;}
function notificationsPage(){return `<section class="panel full-notifications"><div class="panel-heading"><div class="panel-title">${icon('bell')}<h3>Les nouvelles de vos sociétés</h3></div><button class="text-link" data-action="read-all">Tout marquer comme lu ${icon('check')}</button></div>${notificationList()}</section>`;}
function accountPage(){return `<div class="account-page-grid"><section class="panel"><div class="panel-heading"><div class="panel-title">${icon('users')}<h3>Mes informations personnelles</h3></div></div><form id="profile-form" class="profile-form"><div class="profile-intro"><span class="profile-large-avatar">${escapeHTML(initials())}</span><span><strong>${escapeHTML(fullName())}</strong><small>Votre profil personnel</small></span></div><div class="form-row">${field('firstname','Prénom',profile.firstname,'text','maxlength="60"')}${field('lastname','Nom',profile.lastname,'text','maxlength="60"')}</div><div class="form-field"><label for="profile-email">Adresse e-mail · facultatif</label><input id="profile-email" name="email" type="email" autocomplete="email" value="${escapeHTML(profile.email)}" placeholder="vous@entreprise.fr" maxlength="120"></div><p class="demo-note">Les modifications du profil sont conservées uniquement dans ce navigateur pour la démonstration. Aucun mot de passe n’est enregistré.</p><div class="profile-actions"><span id="profile-save-status" role="status"></span><button class="button button-primary" type="submit">Enregistrer les modifications</button></div></form></section><aside class="account-side"><section class="dashboard-tip"><span>${icon('shield')}VOTRE COMPTE</span><h3>Votre profil.<br>Vos sociétés.</h3><p>Un seul espace personnel pour accéder aux sociétés que vous avez ajoutées.</p><a href="#espace" class="text-link">Retour à mon espace ${icon('arrow')}</a></section><section class="panel account-summary"><div>${icon('building')}<strong>${companies.length} société${companies.length>1?'s':''}</strong><span>dans votre espace</span></div><a href="landing.html" class="button">Retour au site ${icon('external')}</a></section></aside></div>`;}
function addCompany(){modal('Ajouter une société',`<p class="modal-description">Renseignez les informations de votre société. Vous pourrez compléter sa fiche dans son espace.</p><form id="add-company-form">${orgAddCompanyFields()}${field('name','Dénomination sociale','','text','maxlength="120"')}${field('siren','Numéro SIREN','','text','inputmode="numeric" pattern="[0-9 ]+" minlength="9" maxlength="11"')}<div class="form-row"><div class="form-field"><label for="add-form">Forme juridique · facultatif</label><input id="add-form" name="form" placeholder="SAS, SARL…" maxlength="100"></div><div class="form-field"><label for="add-city">Code postal et ville · facultatif</label><input id="add-city" name="city" placeholder="75001 Paris" maxlength="150"></div></div><p class="demo-note">Ajout local de démonstration. Aucun appel INPI ni accès à des documents privés n’est effectué.</p><div id="add-company-status" class="add-company-status" role="status"></div>${formActions('Ajouter à mon espace')}</form>`);}
function companiesPicker(){orgCompaniesPicker();}
function emptyCompanyView(title,description,action,label){return `<div class="alternate-view">${sectionIntro(title,description)}<section class="panel empty-state">${icon('folder')}<h3>Votre espace est prêt à être complété.</h3><p>Aucun élément n’a encore été ajouté pour ${escapeHTML(company.name)}.</p><button class="button button-primary" data-action="${action}">${icon('plus')}${label}</button></section></div>`;}
function companyBanner(){return `<section class="company-identity" aria-label="Identité de la société"><div class="company-identity-main"><div class="company-identity-monogram">${escapeHTML(company.name.charAt(0))}<span>${icon('building')}</span></div><div class="company-identity-copy"><div class="company-identity-eyebrow">VOTRE SOCIÉTÉ <span>RG ${currentCompany.example?'00156':'· NOUVEL ESPACE'}</span></div><div class="company-identity-title"><h2>${escapeHTML(company.name)}</h2><span class="badge ${currentCompany.example?'':'orange'}">${currentCompany.example?'En activité':'À compléter'}</span></div><p class="company-identity-legal">${escapeHTML(company.form)}</p><p class="company-identity-location">${icon('pin')}<span>${escapeHTML(company.street)} · ${escapeHTML(company.city)} · France</span></p></div></div><div class="company-identity-actions"><button class="button" data-action="export">${icon('download')}Exporter la fiche</button><button class="text-link" data-action="edit">${icon('edit')}Modifier les informations</button></div><div class="company-identity-bottom"><span>${icon('file')}SIREN <button class="identity-copy-number" data-copy="${escapeHTML(company.siren)}" aria-label="Copier le SIREN">${escapeHTML(company.siren)} ${icon('file')}</button></span><span>${icon('calendar')}Créée le <strong>${escapeHTML(company.created)}</strong></span><span>${icon('building')}<strong>${escapeHTML(company.activity)}</strong></span></div></section>`;}
function companyMetrics(){const data=getOwnership(),ready=data.total>0;return `<section class="company-metrics" aria-label="Chiffres clés de la société"><article><span class="company-metric-icon">${icon('building')}</span><div><span>Capital social</span><strong>${ready?frNumber(data.total*data.nominalCents/100,data.total*data.nominalCents%100?2:0)+' <small>€</small>':'—'}</strong><small>${ready?'Capital renseigné':'À renseigner'}</small></div></article><article><span class="company-metric-icon">${icon('users')}</span><div><span>Associés</span><strong>${String(data.associates.length).padStart(2,'0')}</strong><a href="#associes">Voir les associés ${icon('arrow')}</a></div></article><article><span class="company-metric-icon">${icon('file')}</span><div><span>Titres émis</span><strong>${ready?frNumber(data.total):'—'}</strong><small>${ready?'Valeur nominale de '+money(data.nominalCents):'À renseigner'}</small></div></article><article class="company-metric-status"><span class="company-metric-icon">${icon('shield')}</span><div><span>Vos registres</span><strong>${currentCompany.example?'À jour':'À compléter'}</strong><a href="#titres">Consulter les registres ${icon('arrow')}</a></div></article></section>`;}
function companyCapital(){const data=getOwnership();return `<section class="panel company-capital-card"><div class="panel-heading"><div class="panel-title">${icon('users')}<h3>Capital & actionnariat</h3></div><button class="capital-help-button" data-action="capital-help" aria-label="Comprendre le capital social">${icon('help')}</button></div>${data.total||data.associates.length?`<div class="company-capital-total"><span>Capital social</span><strong>${money(data.total*data.nominalCents)}</strong><span class="company-capital-tag">${icon('check')}Capital renseigné</span></div><div class="company-capital-chart">${ownershipDonut(data,true)}<div class="capital-legend">${capitalSegments(data).slice(0,5).map(item=>`<div class="legend-row"><i class="legend-dot" style="background:${item.color}"></i><span>${escapeHTML(item.name)}<small>${frNumber(item.shares)} titres</small></span><strong>${frNumber(sharePercent(item.shares,data),2)} %</strong></div>`).join('')}${capitalSegments(data).length>5?'<a class="text-link" href="#associes">Voir les '+capitalSegments(data).length+' participations</a>':''}</div></div><div class="company-capital-details"><div><span>Nombre de titres</span><strong>${frNumber(data.total)} titres</strong></div><div><span>Valeur nominale</span><strong>${money(data.nominalCents)} / titre</strong></div></div><div class="cs-overview-actions"><button class="button" data-action="capital-setup">${icon('edit')}Renseigner le capital</button><a href="#associes">Voir l’actionnariat ${icon('arrow')}</a></div>${data.setup?.observation?`<div class="cs-saved-observation"><strong>Observation</strong><br>${escapeHTML(data.setup.observation)}</div>`:''}`:`<div class="company-capital-empty">${icon('users')}<h3>Votre capital,<br>en toute clarté.</h3><p>Les associés et les titres de cette société n’ont pas encore été renseignés.</p><button class="button" data-action="capital-setup">${icon('plus')}Renseigner le capital</button></div>`}</section>`;}
function companySubscription(){return orgCompanyLicenseCard();}
function companyActivity(){return `<section class="panel company-activity"><div class="panel-heading"><div class="panel-title">${icon('clock')}<h3>Vie de la société</h3></div>${currentCompany.example?'<button class="text-link" data-action="activity">Tout voir '+icon('arrow')+'</button>':''}</div>${currentCompany.example?timeline():`<div class="company-first-step"><span>${icon('building')}</span><div><strong>Votre espace société est prêt.</strong><p>Complétez vos informations, puis préparez vos premiers registres.</p></div><button class="text-link" data-action="edit">Compléter la fiche ${icon('arrow')}</button></div>`}</section>`;}
function overview(){return `${currentCompany.demoFixture?'<p class="volume-demo-notice">Société fictive pour tester l’interface. Nom, coordonnées et identifiants de démonstration ; aucune vérification INPI.</p>':''}${companyBanner()}${companyMetrics()}<div class="company-overview-grid"><div class="company-overview-left">${informationPanel()}${companyActivity()}</div><div class="company-overview-right">${companyCapital()}${companySubscription()}</div></div>`;}
function capitalHelp(){modal('Comprendre votre capital',`<p class="modal-description">Le capital social, les titres et leur répartition réunis dans une même vue.</p><div class="capital-help-items"><div><strong>Le capital social</strong><p>Le montant renseigné pour votre société.</p></div><div><strong>Les titres émis</strong><p>Le nombre d’actions ou de parts qui composent le capital.</p></div><div><strong>La valeur nominale</strong><p>La valeur unitaire d’un titre. Pour cette société : ${money(getOwnership().total*getOwnership().nominalCents)} de capital pour ${frNumber(getOwnership().total)} titres, soit ${money(getOwnership().nominalCents)} par titre.</p></div><div><strong>La répartition</strong><p>Le pourcentage de titres détenus par chaque associé. La répartition affichée est calculée à partir des titres renseignés pour cette société.</p></div></div>${demoNote}`);}
function invoices(){modal('Les factures de '+escapeHTML(company.name),`<div class="invoice-empty">${icon('file')}<h3>Vos factures, au même endroit.</h3><p>Aucune facture n’est disponible dans cette démonstration. Cet espace présentera les factures associées à cette société.</p></div><a class="button invoice-offer-link" href="offres.html">Consulter les offres ${icon('arrow')}</a>`);}
function buyCertifications(){modal('Ajouter des certifications',`<p class="modal-description">Préparez une demande de certifications pour ${escapeHTML(company.name)}. Le tarif et le solde devront être confirmés avant tout achat.</p><form data-demo-form="Demande de certifications">${field('quantity','Nombre de certifications souhaitées','5','number','min="1" max="1000"')}<p class="demo-note">Démonstration : la demande est téléchargée en brouillon. Aucun achat ni paiement n’est effectué. Le solde affiché dans la capture d’origine nécessite une vérification.</p>${formActions('Préparer ma demande')}</form>`);}

function updateProfileUI(){const name=fullName();$$('.account .avatar,.topbar .avatar').forEach(el=>el.textContent=initials());$('.account strong').textContent=name;}
function updateNotificationUI(){$$('.nav-notification-count').forEach(el=>{el.textContent=unreadCount();el.hidden=!unreadCount();});}
function markAllRead(){notificationRead=[...new Set([...notificationRead,...organizationNotifications().map(n=>n.id)])];saveNotificationRead();render();toast('Toutes les notifications sont marquées comme lues.');}
function saveNotificationRead(){try{localStorage.setItem('rg-demo-notifications-read',JSON.stringify(notificationRead));}catch{}updateNotificationUI();}

function administration(){return renderAccessAdministration();}
const views = {organisation:organizationPage,espace:personalDashboard,compte:accountPage,notifications:notificationsPage,societe:overview,associes:associates,titres:titles,decisions,personnel,documents:documentView,procedures,administration};
function render(){const subnavFocused=!!document.activeElement?.closest('[data-subnav]');const requested=location.hash.slice(1)||document.body.dataset.defaultView||'societe';const operationRoute=/^operation\/([a-zA-Z0-9_-]+)$/.exec(requested);operationViewId=operationRoute?operationRoute[1]:null;const associateRoute=/^associes\/(\d+)$/.exec(requested);associateViewId=associateRoute?associateRoute[1]:null;activeTab=operationRoute?'titres':associateRoute?'associes':requested.startsWith('organisation/')?'organisation':requested.startsWith('administration/')?'administration':views[requested]?requested:(views[document.body.dataset.defaultView]?document.body.dataset.defaultView:document.body.dataset.defaultView?.startsWith('associes/')?'associes':'societe');const personal=['espace','organisation','compte','notifications'].includes(activeTab);if(!personal)orgAlignCompanyContext(currentCompany.id);document.body.classList.toggle('company-detail',!personal);document.body.classList.toggle('associates-active',activeTab==='associes');document.body.classList.toggle('associate-paper-active',activeTab==='associes'&&!!associateViewId);$('#view').innerHTML=views[activeTab]();$('#view').setAttribute('aria-label',personal?'Contenu de mon espace personnel':'Contenu de la société');$('.tabs').hidden=personal;$('.company-nav').hidden=personal;$('.sidebar').classList.toggle('personal-sidebar',personal);$$('[data-tab]').forEach(el=>{el.classList.toggle('active',el.dataset.tab===activeTab);if(el.dataset.tab===activeTab)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});$$('[data-nav]').forEach(el=>{const key=personal?activeTab:'societe';el.classList.toggle('active',el.dataset.nav===key);if(el.dataset.nav===key)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});const titles={organisation:orgGroup().name,associes:'Les associés',espace:'Bonjour '+(profile.firstname||'à vous'),compte:'Mon compte',notifications:'Mes notifications'};$('.page-heading .eyebrow').hidden=false;$('.page-heading .eyebrow').textContent=personal?'VOTRE ESPACE PERSONNEL':'VOTRE ESPACE JURIDIQUE';$('.page-heading h1').innerHTML=escapeHTML(titles[activeTab]||company.name)+'<span class="heading-dot">.</span>';$('.page-heading p').hidden=!personal&&activeTab!=='associes';$('.page-heading p').textContent=activeTab==='espace'?'Un coup d’œil sur vos sociétés. Et vous voilà à jour.':activeTab==='compte'?'Vos informations personnelles, à votre rythme.':activeTab==='notifications'?'Retrouvez les nouvelles de toutes vos sociétés.':activeTab==='associes'?'L’actionnariat de '+company.name+', en toute clarté.':'';const button=$('.page-heading>.button');button.hidden=['compte','organisation'].includes(activeTab)||(!personal&&activeTab!=='associes');button.dataset.action=personal?'add-company':activeTab==='associes'?'add-associate':'new-procedure';button.innerHTML=icon('plus')+(personal?'Ajouter une société':activeTab==='associes'?'Ajouter un associé':'Nouvelle procédure');$('[data-tab="associes"] span').textContent=getOwnership().associates.length;document.title=(personal?({organisation:'Organisation',espace:'Mon espace',compte:'Mon compte',notifications:'Notifications'}[activeTab]):company.name)+' · Registre Général';$('.workspace-name strong').textContent=personal?'Choisir une société':company.name;$('.workspace-name>span').textContent=personal?orgCompaniesInContext().length+' société'+(orgCompaniesInContext().length>1?'s':'')+' dans ce périmètre':'Espace société';$('.workspace-avatar').firstChild.textContent=personal?'↔':company.name.charAt(0);const societyLink=$('[data-nav="societe"]');societyLink.innerHTML=icon('building')+'Ma société'+'<span class="nav-active-dot"></span>';$$('[data-company-dropdown]').forEach(button=>{const current=button.dataset.companyDropdown==='registers'?['titres','decisions','personnel'].includes(activeTab):activeTab==='procedures';button.classList.toggle('active',current);});closeCompanyMenus();updateProfileUI();updateNotificationUI();document.body.classList.remove('menu-open');$('.app-mobile-menu')?.setAttribute('aria-expanded','false');RGSubnav.hydrate();syncOrganizationSidebar();orgApplyCompanyViewPolicy();if(subnavFocused)$('.rg-subnav [aria-current=page]')?.focus({preventScroll:true});}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3600);}
function modal(title,body,eyebrow='REGISTRE GÉNÉRAL'){const dialog=$('#modal');dialog.classList.remove('access-wide','capital-wide','org-wide');$('#modal-title').innerHTML=`<div class="eyebrow">${eyebrow}</div><h2 id="modal-heading">${title}</h2>`;$('#modal-body').innerHTML=body;if(!dialog.open)dialog.showModal();dialog.scrollTop=0;}
function field(name,label,value='',type='text',extra=''){return `<div class="form-field"><label for="field-${name}">${label}</label><input id="field-${name}" name="${name}" type="${type}" value="${escapeHTML(value)}" required ${extra}></div>`;}
const formActions = (label='Enregistrer') => `<div class="modal-actions"><button type="button" class="button" data-action="close-modal">Annuler</button><button class="button button-primary" type="submit">${label}</button></div>`;
function download(filename,content,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Votre fichier a été téléchargé.');}
let generalSyncDraft=[];
function edit(){generalSyncDraft=[];modal('Informations générales',`<p class="modal-description">Mettez à jour les informations de ${escapeHTML(company.name)}. Les modifications restent dans ce navigateur.</p><div class="general-edit-tabs" role="tablist" aria-label="Mode de modification"><button type="button" role="tab" id="general-tab-manual" aria-controls="general-panel-manual" aria-selected="true" data-general-mode="manual">${icon('edit')}Saisie manuelle</button><button type="button" role="tab" id="general-tab-auto" aria-controls="general-panel-auto" aria-selected="false" tabindex="-1" data-general-mode="auto">${icon('refresh')}Mise à jour automatique</button></div><div id="general-panel-manual" role="tabpanel" aria-labelledby="general-tab-manual"><form id="edit-form">${field('name','Dénomination sociale',company.name,'text','maxlength="180"')}${field('form','Forme juridique',company.form)}${field('activity','Activité principale',company.activity)}${field('street','Adresse du siège',company.street)}${field('city','Code postal et ville',company.city)}${field('closing','Clôture de l’exercice',company.closing)}<div id="general-manual-status" class="general-manual-status" role="status"></div>${formActions()}</form></div><div id="general-panel-auto" role="tabpanel" aria-labelledby="general-tab-auto" hidden><div class="general-auto-intro"><span>${icon('refresh')}</span><h3>Une fiche actualisée.<br>En quelques clics.</h3><p>Vérifiez les informations publiques de la société, comparez les changements et choisissez les champs à préremplir.</p><div class="general-auto-siren">SIREN <strong>${escapeHTML(company.siren)}</strong><small>Simulation</small></div><button class="button button-primary" type="button" data-action="general-auto-check">${icon('refresh')}Vérifier les mises à jour</button></div><p class="general-auto-note">Mode démonstration : aucun appel INPI. La simulation utilise uniquement la fiche d’exemple THIRTY ; les données présentées ne sont pas une vérification en temps réel.</p><div id="general-auto-results" aria-live="polite"></div></div>`);}
function setGeneralMode(mode,focus=false){if(!$('#general-panel-manual'))return;const automatic=mode==='auto';$('#general-panel-manual').hidden=automatic;$('#general-panel-auto').hidden=!automatic;$$('[data-general-mode][role=tab]').forEach(button=>{const selected=button.dataset.generalMode===mode;button.setAttribute('aria-selected',selected);button.tabIndex=selected?0:-1;if(selected&&focus)button.focus();});}
function previewGeneralUpdate(){const form=$('#edit-form'),target=$('#general-auto-results');if(!form||!target)return;generalSyncDraft=[];if(company.siren.replace(/\D/g,'')!==initialCompany.siren.replace(/\D/g,'')){target.innerHTML=`<div class="general-sync-empty">${icon('help')}<strong>Pas de fiche d’exemple pour ce SIREN.</strong><p>Vous pouvez renseigner les informations manuellement. Aucun service externe n’est interrogé dans cette démonstration.</p><button class="text-link" type="button" data-general-mode="manual">Revenir à la saisie manuelle ${icon('arrow')}</button></div>`;return;}const labels={name:'Dénomination sociale',form:'Forme juridique',activity:'Activité principale',street:'Adresse du siège',city:'Code postal et ville'};for(const [key,label] of Object.entries(labels)){const before=form.elements[key].value.trim(),after=initialCompany[key];generalSyncDraft.push({key,label,before,after,changed:before!==after});}const changed=generalSyncDraft.filter(item=>item.changed).length;target.innerHTML=`<div class="general-sync-heading"><strong>${changed?changed+' modification'+(changed>1?'s':'')+' proposée'+(changed>1?'s':''):'Les informations correspondent à la fiche d’exemple.'}</strong><span>5 champs comparés · Données de démonstration</span></div><div class="general-sync-fields">${generalSyncDraft.map(item=>`<div class="general-sync-row ${item.changed?'has-change':''}">${item.changed?`<input id="sync-${item.key}" type="checkbox" data-sync-field="${item.key}" checked aria-label="Préremplir ${item.label}">`:`<span class="general-sync-check">${icon('check')}</span>`}<div><label ${item.changed?'for="sync-'+item.key+'"':''}>${item.label}<small>${item.changed?'Modification proposée':'Identique'}</small></label>${item.changed?`<p class="sync-before"><span>Saisie actuelle</span>${escapeHTML(item.before||'Non renseigné')}</p><p class="sync-after"><span>Fiche d’exemple</span>${escapeHTML(item.after)}</p>`:`<p>${escapeHTML(item.after)}</p>`}</div></div>`).join('')}</div>${changed?`<button class="button button-primary general-sync-apply" type="button" data-action="general-auto-apply">${icon('check')}Préremplir les champs sélectionnés</button><p class="general-auto-note">Vous pourrez relire les champs puis enregistrer la fiche. La clôture de l’exercice reste inchangée.</p>`:'<button class="button general-sync-apply" type="button" data-general-mode="manual">Revenir à la fiche '+icon('arrow')+'</button>'}`;}
function applyGeneralUpdate(){const form=$('#edit-form');if(!form)return;let count=0;for(const item of generalSyncDraft){if(!item.changed||!$('#sync-'+item.key)?.checked)continue;form.elements[item.key].value=item.after;form.elements[item.key].classList.add('general-field-updated');count++;}if(!count){toast('Sélectionnez au moins un champ à préremplir.');return;}setGeneralMode('manual');$('#general-manual-status').textContent=count+' champ'+(count>1?'s':'')+' prérempli'+(count>1?'s':'')+'. Relisez la fiche, puis enregistrez vos modifications.';$('#general-tab-manual').focus();}
function closeCompanyMenus(returnFocus=false){$$('[data-company-dropdown]').forEach(button=>{const open=button.getAttribute('aria-expanded')==='true';button.setAttribute('aria-expanded','false');document.getElementById(button.getAttribute('aria-controls')).hidden=true;if(open&&returnFocus)button.focus();});}
function newProcedure(){modal('Que souhaitez-vous faire ?',`<p class="modal-description">Choisissez votre démarche. Nous vous accompagnons à chaque étape.</p>${[{action:'accounts',icon:'download',title:'Déposer les comptes annuels',sub:'Préparez le dossier de votre exercice.'},{action:'announcement',icon:'file',title:'Publier une annonce légale',sub:'Préparez une publication pour votre société.'},{action:'movement',icon:'users',title:'Enregistrer un mouvement de titres',sub:'Cession, donation ou souscription.'}].map(x=>`<button class="modal-option" data-action="${x.action}"><span class="action-icon">${icon(x.icon)}</span><span><strong>${x.title}</strong><small>${x.sub}</small></span>${icon('arrow')}</button>`).join('')}${demoNote}`);}
function accounts(){modal('Déposer les comptes annuels',`<p class="modal-description">Préparez votre dossier en sélectionnant l’exercice et votre document comptable.</p><form data-demo-form="Dépôt des comptes annuels"><div class="form-field"><label for="year">Exercice comptable</label><select name="year" id="year"><option>2025</option><option>2024</option><option>2023</option></select></div><div class="form-field"><label for="accounts-file">Comptes annuels · PDF</label><div class="file-drop"><input name="document" id="accounts-file" type="file" accept=".pdf" required></div></div>${demoNote}${formActions('Préparer le dossier')}</form>`);}
function announcement(){modal('Votre annonce légale',`<p class="modal-description">Rassemblez les éléments nécessaires à la rédaction de votre annonce.</p><form data-demo-form="Annonce légale"><div class="form-field"><label for="announcement-type">Type d’annonce</label><select id="announcement-type" name="type"><option>Modification de société</option><option>Transfert de siège social</option><option>Changement de dirigeant</option><option>Modification du capital</option></select></div>${field('date','Date de la décision','','date')}<div class="form-field"><label for="announcement-details">Détails de la modification</label><textarea id="announcement-details" name="details" placeholder="Décrivez les changements à publier…" required></textarea></div>${demoNote}${formActions('Préparer l’annonce')}</form>`);}
function movement(){newRegisterOperation();}
function upload(kind='document'){const isDecision=kind==='decision';modal(isDecision?'Ajouter une décision':'Ajouter un document',`<p class="modal-description">Sélectionnez un document pour préparer son ajout à votre espace.</p><form data-demo-form="${isDecision?'Décision':'Document'}">${field('title',isDecision?'Intitulé de la décision':'Nom du document')}<div class="form-field"><label for="upload-file">Document · PDF</label><div class="file-drop"><input id="upload-file" name="document" type="file" accept=".pdf" required></div></div>${demoNote}${formActions('Préparer l’ajout')}</form>`);}
function notifications(){location.href='dashboard.html#notifications';}
const searchItems=[{name:'Mon espace personnel',tab:'espace',icon:'grid'},{name:'Mes notifications',tab:'notifications',icon:'bell'},{name:'Mon compte',tab:'compte',icon:'users'},{name:'Informations de la société',tab:'societe',icon:'building'},{name:'Associés et répartition du capital',tab:'associes',icon:'users'},{name:'Registre de titres',tab:'titres',icon:'file'},{name:'Registre des décisions',tab:'decisions',icon:'file'},{name:'Registre du personnel',tab:'personnel',icon:'users'},{name:'Documents sociaux',tab:'documents',icon:'folder'},{name:'Mes procédures en cours',tab:'procedures',icon:'clock'},{name:'Administration, gestion des droits et rôles',tab:'administration',icon:'settings'}];
function search(){modal('Rechercher dans votre espace',`<label class="sr-only" for="global-search">Votre recherche</label><input id="global-search" class="search-input" placeholder="Société, document, registre…" autocomplete="off"><ul class="search-results" id="search-results"></ul>`);renderSearch('');$('#global-search').focus();}
function renderSearch(query){const normalized=value=>value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const results=searchItems.filter(item=>normalized(item.name).includes(normalized(query)));$('#search-results').innerHTML=results.length?results.map(item=>`<li><a href="#${item.tab}" data-action="close-modal">${icon(item.icon)}${item.name}${icon('arrow')}</a></li>`).join(''):'<li class="modal-description" style="padding:15px 10px">Aucun résultat pour cette recherche.</li>';}
const actions={
  'associate-account-settings':editAssociateAccount,'associate-invite':inviteAssociate,'associate-auth-help':associateAuthenticationHelp,'associate-certificate':certificatePreview,'associate-certificate-download':downloadCertificate,'associate-account-download':downloadAssociateAccount,'associate-account-print':printAssociateAccount,
  'associate-scroll-account':()=>$('#compte-associe')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'}),
  'general-auto-check':previewGeneralUpdate,'general-auto-apply':applyGeneralUpdate,
  'add-associate':()=>editAssociate(),'edit-capital':editCapital,'security-details':securityDetails,'export-associates':downloadAssociates,
  'capital-setup':startCapitalSetup,'capital-help':capitalHelp,invoices,'buy-certifications':buyCertifications,
  edit,'new-procedure':newProcedure,accounts,announcement,movement,notifications,search,
  upload:()=>upload(),decision:()=>pvForm(),
  'close-modal':()=>$('#modal').close(),
  menu:()=>{const open=document.body.classList.toggle('menu-open');$('.app-mobile-menu')?.setAttribute('aria-expanded',String(open));},
  'close-menu':()=>{document.body.classList.remove('menu-open');$('.app-mobile-menu')?.setAttribute('aria-expanded','false');},
  export:()=>download(`${company.name}-fiche-societe.txt`,`REGISTRE GÉNÉRAL — FICHE SOCIÉTÉ\nMaquette de démonstration\n\n${Object.entries(company).map(([k,v])=>`${k} : ${v}`).join('\n')}\n\nCapital social : ${money(getOwnership().total*getOwnership().nominalCents)}\nTitres : ${frNumber(getOwnership().total)}\nAssociés : ${getOwnership().associates.length}\n`),
  'export-capital':downloadCapital,
  activity:()=>modal('L’activité de votre société',`<p class="modal-description">Retrouvez les dernières mises à jour de votre espace.</p>${timeline(true)}`),
  employee:()=>personForm('employees'),
  companies:companiesPicker,
  'add-company':addCompany,
  'read-all':markAllRead,
  'all-procedures':()=>{const entry=orgCompaniesInContext().find(c=>c.example);if(entry)openCompany(entry.id,'procedures');else toast('Aucune procédure n’a encore été ajoutée.');},
  account:()=>{location.href='dashboard.html#compte';},
  reset:()=>{Object.assign(company,currentCompany.example?initialCompany:{...blankCompany,name:company.name,siren:company.siren});persistWorkspace();settings.reminders=true;settings.digest=false;$('#modal').close();render();toast('La fiche de cette société a été réinitialisée.');},
  help:()=>modal('Un coup de main ?',`<p class="modal-description">Retrouvez rapidement votre chemin dans cette nouvelle interface.</p>${[{title:'Mettre à jour ma société',text:'Depuis la vue d’ensemble, cliquez sur « Modifier » dans les informations générales.'},{title:'Consulter mon actionnariat',text:'L’onglet « Associés » présente la répartition du capital et permet de l’exporter.'},{title:'Préparer une formalité',text:'Le menu « Mes formalités » donne accès au dépôt des comptes et aux annonces légales. Les mouvements sont accessibles depuis « Registres ».'}].map(x=>`<div class="notification-item"><span class="action-icon">${icon('help')}</span><div><strong>${x.title}</strong><p>${x.text}</p></div></div>`).join('')}`),
  plans:()=>{location.href='offres.html';}
};
document.addEventListener('click',async event=>{
  const menuTrigger=event.target.closest('[data-company-dropdown]');if(menuTrigger){const open=menuTrigger.getAttribute('aria-expanded')==='true';closeCompanyMenus();menuTrigger.setAttribute('aria-expanded',!open);document.getElementById(menuTrigger.getAttribute('aria-controls')).hidden=open;}else if(event.target.closest('.company-dropdown-panel a,.company-dropdown-panel button'))closeCompanyMenus(!!event.target.closest('.company-dropdown-panel button'));else if(!event.target.closest('.company-tab-dropdown'))closeCompanyMenus();
  const generalMode=event.target.closest('[data-general-mode]');if(generalMode)setGeneralMode(generalMode.dataset.generalMode);
  const action=event.target.closest('[data-action]');if(action&&actions[action.dataset.action]) actions[action.dataset.action]();
  const associateEdit=event.target.closest('[data-associate-edit]');if(associateEdit)editAssociate(associateEdit.dataset.associateEdit);
  const sorting=event.target.closest('[data-associate-sort]');if(sorting){associatePage=1;const key=sorting.dataset.associateSort;associateSort={key,direction:associateSort.key===key?-associateSort.direction:1};refreshAssociateTable();}
  const opening=event.target.closest('[data-company-open]');if(opening)openCompany(opening.dataset.companyOpen);
  const notification=event.target.closest('[data-notification-open]');if(notification){const item=workspaceNotifications.find(n=>n.id===notification.dataset.notificationOpen);if(item){if(!notificationRead.includes(item.id))notificationRead.push(item.id);saveNotificationRead();openCompany(item.companyId,item.tab);}}
  const reading=event.target.closest('[data-notification-read]');if(reading){if(!notificationRead.includes(reading.dataset.notificationRead))notificationRead.push(reading.dataset.notificationRead);saveNotificationRead();render();}
  const copy=event.target.closest('[data-copy]');if(copy){try{await navigator.clipboard.writeText(copy.dataset.copy);toast('Numéro copié dans le presse-papiers.');}catch{modal('Copier le numéro',`<p class="modal-description">Sélectionnez le numéro ci-dessous pour le copier.</p><input class="search-input" readonly value="${escapeHTML(copy.dataset.copy)}">`);$('#modal-body input').select();}}
  const setting=event.target.closest('[data-setting]');if(setting){settings[setting.dataset.setting]=!settings[setting.dataset.setting];setting.setAttribute('aria-checked',settings[setting.dataset.setting]);persistWorkspace();toast('Préférence de démonstration mise à jour.');}
  const doc=event.target.closest('[data-document]');if(doc){const data=documents[Number(doc.dataset.document)];download(`${data.name}.txt`,`REGISTRE GÉNÉRAL — DOCUMENT DE DÉMONSTRATION\n\n${data.name}\nSociété : ${company.name}\nDate : ${data.date}\n\nDocument illustratif sans valeur juridique.\n`);}
});
document.addEventListener('input',event=>{if(event.target.id==='associate-search'){associateQuery=event.target.value;associatePage=1;refreshAssociateTable();}if(event.target.id==='security-search'){securityQuery=event.target.value;$('#security-table-body').innerHTML=securityRows();}if(event.target.closest('#capital-form')){const form=$('#capital-form'),total=Number(form.elements.total.value),nominal=Number(form.elements.nominal.value);$('#capital-preview').textContent=Number.isFinite(total*nominal)&&total>=0&&nominal>0?money(Math.round(total*nominal*100)):'—';}if(event.target.id==='global-search')renderSearch(event.target.value);if(event.target.id==='company-filter')updateCompanyFilter();if(event.target.id==='field-siren')event.target.setCustomValidity('');});
document.addEventListener('change',event=>{if(event.target.id==='associate-kind'&&$('#associate-form')){const person=event.target.value==='Personne physique';$('.associate-person-fields').hidden=!person;$('.associate-person-fields').disabled=!person;$('.associate-entity-fields').hidden=person;$('.associate-entity-fields').disabled=person;}if(event.target.id==='company-sort')updateCompanyFilter();});
function updateCompanyFilter(reset=true){companyQuery=$('#company-filter').value;companySort=$('#company-sort').value;if(reset)companyPage=1;$('#company-card-grid').innerHTML=companyCards();$('#company-pagination').innerHTML=companyPagination();$('#company-filter-status').textContent=filteredCompanies().length+' société(s) trouvée(s).';}
document.addEventListener('submit',event=>{
  if(event.target.id==='associate-account-form'){event.preventDefault();saveAssociateAccount(event.target);}
  if(event.target.id==='associate-invitation-form'){event.preventDefault();prepareAssociateInvitation(event.target);}
  if(event.target.id==='capital-form'){event.preventDefault();saveCapitalForm(event.target);}
  if(event.target.id==='associate-form'){event.preventDefault();saveAssociateForm(event.target);}
  if(event.target.id==='add-company-form'){event.preventDefault();saveCompanyWithOrganization(event.target);}
  if(event.target.id==='profile-form'){event.preventDefault();const data=new FormData(event.target);const first=String(data.get('firstname')).trim(),last=String(data.get('lastname')).trim();if(!first||!last){toast('Renseignez votre prénom et votre nom.');return;}profile={firstname:first.slice(0,60),lastname:last.slice(0,60),email:String(data.get('email')).trim().slice(0,120)};let saved=true;try{localStorage.setItem('rg-demo-profile',JSON.stringify(profile));sessionStorage.setItem('rg-demo-profile',JSON.stringify({firstname:profile.firstname,lastname:profile.lastname}));}catch{saved=false;}render();$('#profile-save-status').textContent=saved?'Modifications enregistrées.':'Modifications conservées pour cette session.';toast('Votre profil a été mis à jour.');}

  if(event.target.id==='edit-form'){event.preventDefault();const data=new FormData(event.target);for(const key of ['name','form','activity','street','city','closing']) company[key]=String(data.get(key)).trim();persistWorkspace();$('#modal').close();render();toast('Les informations de votre société ont été mises à jour.');}
  if(event.target.matches('[data-demo-form]')){event.preventDefault();const form=event.target;const data=new FormData(form);const details=[`REGISTRE GÉNÉRAL — BROUILLON DE DÉMONSTRATION`,`Démarche : ${form.dataset.demoForm}`,`Société : ${company.name}`,...[...data.entries()].map(([key,value])=>`${key} : ${value instanceof File ? value.name : value}`),'','Ce brouillon local ne déclenche aucune démarche officielle.'];download('brouillon-demonstration.txt',details.join('\n'));$('#modal').close();toast('Brouillon téléchargé. Aucune démarche n’a été transmise.');}
});
document.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();search();}if(event.key==='Escape'){closeCompanyMenus(true);if(document.body.classList.contains('menu-open')){document.body.classList.remove('menu-open');$('.app-mobile-menu')?.setAttribute('aria-expanded','false');$('.app-mobile-menu')?.focus();}}const menu=event.target.closest('[data-company-dropdown]');if(menu&&['ArrowDown','ArrowUp'].includes(event.key)){event.preventDefault();closeCompanyMenus();menu.setAttribute('aria-expanded','true');const panel=document.getElementById(menu.getAttribute('aria-controls'));panel.hidden=false;const items=[...panel.querySelectorAll('a,button')];(event.key==='ArrowUp'?items.at(-1):items[0])?.focus();}const mode=event.target.closest('[data-general-mode][role=tab]');if(mode&&['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();setGeneralMode(event.key==='Home'?'manual':event.key==='End'?'auto':mode.dataset.generalMode==='manual'?'auto':'manual',true);}});
$('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const rect=$('#modal').getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)$('#modal').close();}});
window.addEventListener('afterprint',()=>document.body.classList.remove('print-associate-ledger'));
window.addEventListener('hashchange',render);
render();

document.addEventListener('click',event=>{const control=event.target.closest('[data-collection-page]');if(!control)return;const page=Number(control.dataset.collectionPage);if(control.dataset.collection==='companies'){companyPage=page;updateCompanyFilter(false);}if(control.dataset.collection==='associates'){associatePage=page;refreshAssociateTable();}document.querySelector('[data-pagination="'+control.dataset.collection+'"] [aria-current="page"]')?.focus({preventScroll:true});});
document.addEventListener('change',event=>{const id=event.target.dataset.collectionSize,size=Number(event.target.value);if(id==='companies'&&[6,12,24].includes(size)){companyPageSize=size;companyPage=1;updateCompanyFilter(false);}if(id==='associates'&&[10,20,50].includes(size)){associatePageSize=size;associatePage=1;refreshAssociateTable();}if(['companies','associates'].includes(id))document.getElementById(id+'-page-size')?.focus({preventScroll:true});});
